// src/components/Services.js
import React, { useEffect, useState, useRef } from 'react';
import './Services.css';

const servicesList = [
  "Smart Thermostats",
  "Smart Switches",
  "Smart Sensors",
  "Smart Lighting",
  "Smart Speakers",
  "Supply and Programming of Drivers",
  "Integration components (KNX, DALI)",
  "Lighting Control",
  "Air Conditioning Automation",
  "Music System Integration",
  "Automated Curtain Systems",
  "Office Space Automation",
  "Hotel Space Automation",
  "General Space Automation Systems"
];

const Services = () => {
  const [isVisible, setIsVisible] = useState(false);
  const sectionRef = useRef(null);

  useEffect(() => {
    const observer = new IntersectionObserver(
      entries => {
        entries.forEach(entry => {
          if (entry.isIntersecting) {
            setIsVisible(true);
            observer.disconnect();
          }
        });
      },
      { threshold: 0.2 }
    );

    if (sectionRef.current) {
      observer.observe(sectionRef.current);
    }

    return () => observer.disconnect();
  }, []);

  return (
    <section ref={sectionRef} className={`services-section ${isVisible ? 'visible' : ''}`}>
      <h2>Our Services</h2>
      <div className="services-grid">
        {servicesList.map((service, index) => (
          <div className="service-card" key={index}>
            {service}
          </div>
        ))}
      </div>
    </section>
  );
};

export default Services;
